@st.cache_data(ttl=60)
def load_macro_overrides_from_disk():
    try:
        if MACRO_OVERRIDE_FILE.exists(): return _normalise_macro_upload(pd.read_csv(MACRO_OVERRIDE_FILE))
    except Exception: pass
    return pd.DataFrame(columns=['market','indicator','date','value','unit','source','source_type','notes'])
def get_uploaded_macro_value(market,indicator):
    frames=[]

    # v38q quick-fix source priority:
    # 1) External GitHub Actions pack as default stable source
    # 2) Saved owner override
    # 3) Current session owner upload as explicit override
    external=load_external_macro_pack_from_repo()
    if isinstance(external,pd.DataFrame) and not external.empty:
        e=external.copy(); e['_source_priority']=10; e['_source_layer']='External repo pack'; frames.append(e)

    disk=load_macro_overrides_from_disk()
    if isinstance(disk,pd.DataFrame) and not disk.empty:
        d=disk.copy(); d['_source_priority']=20; d['_source_layer']='Saved override'; frames.append(d)

    if 'macro_upload_df' in st.session_state and isinstance(st.session_state.macro_upload_df,pd.DataFrame) and not st.session_state.macro_upload_df.empty:
        u=st.session_state.macro_upload_df.copy(); u['_source_priority']=30; u['_source_layer']='Session upload'; frames.append(u)

    if not frames:
        return None
    df=pd.concat(frames,ignore_index=True)
    if df.empty:
        return None

    aliases={market,MARKET_UPLOAD_ALIASES.get(market,market)}
    indicators={indicator, 'Jobs' if indicator=='Unemployment' else indicator, 'Unemployment' if indicator=='Jobs' else indicator}
    sub=df[df['market'].astype(str).str.upper().isin({x.upper() for x in aliases}) & df['indicator'].astype(str).str.lower().isin({x.lower() for x in indicators})].copy()
    if sub.empty:
        return None

    sub['_date_sort']=pd.to_datetime(sub['date'],errors='coerce')
    sub=sub.sort_values(['_date_sort','_source_priority','date'],na_position='first')
    r=sub.iloc[-1]
    return {
        'value':float(r['value']),
        'date':str(r.get('date','')),
        'unit':str(r.get('unit','')),
        'source':str(r.get('source','External repo pack')),
        'source_type':str(r.get('source_type','External repo pack')),
        'source_layer':str(r.get('_source_layer',''))
    }

def _uploaded_result(uploaded):
    unit=uploaded.get('unit',''); display=f"{uploaded['value']:.1f}{unit}" if unit and '%' in unit else (f"{uploaded['value']:.1f}" if abs(uploaded['value'])<1000 else f"{uploaded['value']:,.0f}")
    return _source_result(uploaded['value'],display,f"{uploaded.get('source_type','Owner-uploaded')} · {uploaded.get('source','')} · {uploaded.get('date','')}",uploaded.get('source_type','Owner-uploaded'),uploaded.get('date',''))


def _pack_first_macro_result(market, indicator):
    """Return generated/applied macro pack value before any dashboard fallback.

    Governance rule: macro pack / owner-uploaded values are the source of truth for
    monthly macro indicators such as PMI. The base app must not silently substitute
    built-in PMI seeds, session values, or simulated data when the pack is absent.
    """
    uploaded = get_uploaded_macro_value(market, indicator)
    if uploaded is not None:
        return _uploaded_result(uploaded)
    return None


def _is_real_macro_value(res):
    """True only when a resolver result contains a usable numeric macro value."""
    try:
        return isinstance(res, dict) and res.get('value') is not None and pd.notna(float(res.get('value')))
    except Exception:
        return False
def _awaiting_live(source_label, diagnostic='Live fetch unavailable or parser returned no usable value.'):
    return _source_result(None,'Awaiting','', 'Awaiting', diagnostic=f'{source_label} · {diagnostic}')
def _awaiting_validation(source_label): return _source_result(None,'Awaiting validation',source_label,'Needs validation',diagnostic='Official adapter is mapped but still requires runtime validation.')

def rate_card_label(market):
    if market in US_MARKETS: return 'US 10Y Yield'
    if market=='STI': return 'SG Rates'
    if market=='HSI': return 'HK Rates'
    if market=='A-Share': return 'China Rates'
    if market in USD_PROXY_MARKETS: return 'USD Rates Proxy'
    return 'Rates'
def rate_basis_text(market):
    if market in US_MARKETS: return 'Basis: US 10-year Treasury constant maturity yield. Preferred source: FRED DGS10.'
    if market=='STI': return 'Basis: Singapore-dollar interest-rate environment. Preferred basis: SG SORA live redistributor pages that explicitly cite MAS SORA; legacy MAS secure/eservices datastore endpoints removed from active fetch path.'
    if market=='HSI': return 'Basis: Hong Kong-dollar interest-rate environment. Preferred basis: HKMA HIBOR, base rate or discount-window related rates.'
    if market=='A-Share': return 'Basis: China lending-rate benchmark. Preferred basis: CFETS/PBC 1-year Loan Prime Rate, validation mode.'
    if market in USD_PROXY_MARKETS: return 'Basis: US 10-year Treasury yield used as global USD rates / discount-rate proxy.'
    if market=='KLSE':
        return 'Basis: Malaysia policy-rate input. Preferred source: BNM OpenAPI Overnight Policy Rate (OPR).'
    if market=='Nikkei 225':
        return 'Basis: Japan overnight money-market rate. Preferred source: BOJ FM01 STRDCLUCON CSV parser.'
    return 'Basis: selected market interest-rate input where mapped.'
def macro_tooltip_text(display_name, market):
    if display_name=='Unemployment': return 'Basis: official unemployment-rate series, not employment level. US uses FRED UNRATE; Singapore uses SingStat/MOM unemployment where available; Hong Kong uses HKMA unemployment; Malaysia uses OpenDOSM lfs_month u_rate; Japan uses DBnomics STATJP/MIm; China remains NBS validation mode.'
    if display_name=='Claims': return 'Basis: US Initial Jobless Claims / Initial Claims. US markets use FRED ICSA as a labour-stress indicator. Non-US markets show N/A by default unless a comparable official claims series is deliberately mapped.'
    if display_name in ['US 10Y Yield','SG Rates','HK Rates','China Rates','USD Rates Proxy','Rates']: return rate_basis_text(market)+' Source priority: official API/table, owner-upload fallback, then live-fetch diagnostic.'
    return 'Macro data source priority: official API/table, owner-upload fallback, then diagnostic awaiting state.'


def clean_macro_badge(source_type):
    """Executive-facing source badge.
    Keep ingestion method such as Power Query / Pack / Adapter in tooltip, not on-card.
    """
    s=str(source_type or '').strip()
    sl=s.lower()
    if s in ['N/A','']:
        return 'N/A' if s=='N/A' else 'Awaiting'
    if 'pending deployment' in sl:
        return 'Pending deployment'
    if 'official' in sl:
        return 'Official'
    if 'seed' in sl:
        return 'Seed'
    if 'owner' in sl or 'upload' in sl or 'manual' in sl:
        return 'Manual'
    if 'validation' in sl:
        return 'Needs validation'
    if 'await' in sl or 'live fetch' in sl:
        return 'Awaiting'
    return s

def macro_visible_sub(display_name, status_text, source_type, date_text=''):
    """One clean line below the value.
    Source/query/provider details stay in tooltip; the card shows only date or simple state.
    """
    if date_text and str(date_text).strip() and str(date_text).strip()!='N/A':
        return str(date_text).strip()
    s=str(status_text or '').strip()
    if '·' in s:
        parts=[x.strip() for x in s.split('·') if x.strip()]
        if parts:
            last=parts[-1]
            if last and last.lower() not in ['official api','official / pack','official / power query','owner-uploaded','seed / pack']:
                return last
            return ''
    badge=clean_macro_badge(source_type)
    if badge in ['Awaiting','Needs validation','Pending deployment','N/A']:
        return ''
    if s == badge or s.lower() in ['official api','official / pack','official / power query','seed / pack','owner-uploaded']:
        return ''
    return s

def pending_deployment_result(source_label='Pending deployment', diagnostic='Adapter pending deployment.'):
    return _source_result(None,'Pending deployment',source_label,'Pending deployment',diagnostic=diagnostic)

def resolve_macro_value(market,indicator):
    if indicator=='Claims' and market not in US_MARKETS:
        return _source_result(None,'N/A','Not applicable for this market','N/A')
    uploaded=get_uploaded_macro_value(market,indicator)
    if uploaded is not None:
        return _uploaded_result(uploaded)
    if indicator=='PMI':
        packed = _pack_first_macro_result(market, 'PMI')
        if _is_real_macro_value(packed):
            return packed
        return _source_result(None,'Awaiting pack',MACRO_SOURCE_REGISTRY.get(market,{}).get('PMI','Monthly macro pack PMI'),'Awaiting',diagnostic='PMI requires generated/applied macro pack or explicit owner upload; no built-in/session fallback is used for dashboard scoring.')
    if indicator=='Rates':
        if market in US_MARKETS or market in USD_PROXY_MARKETS:
            data=us_macro_dashboard_data()
            if data.get('dgs10') is not None:
                src=data.get('dgs10_source','FRED DGS10')
                return _source_result(data['dgs10'],f"{data['dgs10']:.2f}%",f"Official API · {src} · {data['dgs10_date']}",'Official API',data['dgs10_date'])
            return _awaiting_live('Yahoo ^TNX / FRED DGS10')
        if market=='STI':
            val,dt,src,err=fetch_mas_sora_rate()
            if val is not None: return _source_result(val,f'{val:.2f}%',f'Live source · {src} · {dt}','Live source',dt,err)
            return _awaiting_live('MAS open search.json SORA / domestic rates', err or 'MAS SORA adapter returned no usable value')
        if market=='HSI':
            val,dt,src,err=fetch_hkma_hibor_rate()
            if val is not None: return _source_result(val,f'{val:.2f}%',f'Official API · {src} · {dt}','Official API',dt,err)
            return _awaiting_live('HKMA Open API HIBOR / HKD rates', err or 'HKMA rates adapter returned no usable value')
        if market=='A-Share': return _awaiting_validation('CFETS/PBC 1Y LPR')
        if market=='KLSE':
            val,dt,src,err=fetch_bnm_opr_rate()
            if val is not None: return _source_result(val,f'{val:.2f}%',f'Official API · {src} · {dt}','Official API',dt,err)
            return _awaiting_live('BNM OpenAPI Overnight Policy Rate (OPR)', err or 'BNM OPR adapter returned no usable value')
        if market=='Nikkei 225':
            val,dt,src,err=fetch_boj_overnight_call_rate()
            if val is not None: return _source_result(val,f'{val:.2f}%',f'Official API · {src} · {dt}','Official API',dt,err)
            return _awaiting_live('BOJ FM01 STRDCLUCON CSV parser', err or 'BOJ JP rates adapter returned no usable value')
    if market in US_MARKETS:
        data=us_macro_dashboard_data()
        if indicator=='Inflation' and data.get('inflation_yoy') is not None: return _source_result(data['inflation_yoy'],f"{data['inflation_yoy']:.1f}%",f"Official API · FRED CPI YoY · {data['inflation_date']}",'Official API',data['inflation_date'])
        if indicator in ['Jobs','Unemployment'] and data.get('jobs_rate') is not None: return _source_result(data['jobs_rate'],f"{data['jobs_rate']:.1f}%",f"Official API · FRED UNRATE · {data['jobs_date']}",'Official API',data['jobs_date'])
        if indicator=='Claims' and data.get('claims_k') is not None: return _source_result(data['claims_k'],f"{data['claims_k']:.0f}k",f"Official API · FRED ICSA · {data['claims_date']}",'Official API',data['claims_date'])
        return _awaiting_live(MACRO_SOURCE_REGISTRY.get(market,{}).get(indicator,'FRED'))
    if market=='STI' and indicator in ['Inflation','Jobs','Unemployment']:
        data=singapore_macro_dashboard_data()
        if indicator=='Inflation' and data.get('inflation_yoy') is not None: return _source_result(data['inflation_yoy'],f"{data['inflation_yoy']:.1f}%",f"Official API · SingStat CPI YoY · {data['inflation_date']}",'Official API',data['inflation_date'])
        if indicator in ['Jobs','Unemployment'] and data.get('jobs_rate') is not None: return _source_result(data['jobs_rate'],f"{data['jobs_rate']:.1f}%",f"Official API · SingStat/MOM unemployment · {data['jobs_date']}",'Official API',data['jobs_date'])
        return _awaiting_live(MACRO_SOURCE_REGISTRY.get(market,{}).get('Jobs' if indicator=='Unemployment' else indicator,'SingStat official adapter'),data.get('diagnostic','Live fetch unavailable or row parser returned no usable value.'))
    if market=='HSI' and indicator in ['Inflation','Jobs','Unemployment']:
        data=hkma_macro_dashboard_data()
        if indicator=='Inflation':
            val,dt,src,err=fetch_hk_csd_cpi_yoy_51060001()
            if val is not None:
                return _source_result(val,f'{val:.1f}%',f'Official API · {src} · {dt}','Official API',dt,err)
            return _awaiting_live('C&SD Table 510-60001 Composite CPI YoY', err or 'C&SD CPI YoY adapter returned no usable value')
        if indicator in ['Jobs','Unemployment'] and data.get('jobs_rate') is not None: return _source_result(data['jobs_rate'],f"{data['jobs_rate']:.1f}%",f"Official API · HKMA unemployment · {data['jobs_date']}",'Official API',data['jobs_date'])
        return _awaiting_live(MACRO_SOURCE_REGISTRY.get(market,{}).get('Jobs' if indicator=='Unemployment' else indicator,'HK official adapter'))
    if market=='KLSE' and indicator in ['Jobs','Unemployment']:
        val,dt,src,err=fetch_opendosm_unemployment_rate()
        if val is not None: return _source_result(val,f'{val:.1f}%',f'Official API · {src} · {dt}','Official API',dt,err)
        return _awaiting_live('OpenDOSM lfs_month unemployment rate', err or 'OpenDOSM unemployment adapter returned no usable value')
    if market=='Nikkei 225' and indicator=='Inflation':
        val,dt,src,err=fetch_japan_cpi_yoy_dbnomics()
        if val is not None: return _source_result(val,f'{val:.1f}%',f'Official API · {src} · {dt}','Official API',dt,err)
        return _awaiting_live('DBnomics STATJP/CPIm CPI YoY', err or 'Japan CPI adapter returned no usable value')
    if market=='Nikkei 225' and indicator in ['Jobs','Unemployment']:
        val,dt,src,err=fetch_japan_unemployment_dbnomics()
        if val is not None: return _source_result(val,f'{val:.1f}%',f'Official API · {src} · {dt}','Official API',dt,err)
        return _awaiting_live('DBnomics STATJP/MIm unemployment rate', err or 'Japan unemployment adapter returned no usable value')
    if market=='A-Share' and indicator in ['Inflation','Jobs','Unemployment']:
        return _awaiting_validation(MACRO_SOURCE_REGISTRY.get(market,{}).get('Jobs' if indicator=='Unemployment' else indicator,'NBS official adapter'))
    return _source_result(None,'Awaiting mapping',MACRO_SOURCE_REGISTRY.get(market,{}).get(indicator,'Awaiting official API mapping'),'Awaiting')

